  /* --- mensagem do Nex de manhã / revisão antes de dormir / objetivo --- */
  function nexMsg(){const hr=new Date().getHours(),td=testDays(),due=reviewDue().length,fc=X10.dueCount(),weak=weakTypes(3);const dis=ls.get('x11-msg','');
    if(hr>=20&&hr<24&&fc){if(dis==='n'+today())return'';return'<div class="x11msg night">'+NEX8('dormir',64)+'<div><b>Revisão de 5 minutos antes de dormir</b><span>Rever à noite ajuda a guardar a matéria. São só '+Math.min(5,fc)+' cartões.</span><div class="x11mb"><button class="x8p w sm" data-x11m="bed">Rever agora</button><button class="x8p gh sm" data-x11m="xn">Hoje não</button></div></div></div>';}
    if(dis==='d'+today())return'';let t,a;
    if(td!==null&&td<=7){t=td===0?'O teste é hoje. Uma simulação rápida e estás pronto.':'Faltam '+td+' dia'+(td>1?'s':'')+' para o teste. Segue o plano de hoje.';a=['plan','Ver o plano de hoje'];}
    else if(due){t='Tens '+due+' tipo'+(due>1?'s':'')+' para rever hoje. É o melhor momento para não te esqueceres.';a=['rev','Fazer a revisão'];}
    else if(weak.length){t='Hoje proponho '+esc(TYPES[weak[0].t].n)+'. É onde erras mais.';a=['t'+weak[0].t,'Treinar agora'];}
    else return'';/* 1.27: sem teste, revisão ou ponto fraco, o plano repetia o botão principal do Início */
    return'<div class="x11msg">'+NEX8('incentivar',64)+'<div><b>O plano do Nex para hoje</b><span>'+t+'</span><div class="x11mb"><button class="x8p w sm" data-x11m="'+a[0]+'">'+a[1]+'</button><button class="x8p gh sm" data-x11m="xd">Fechar</button></div></div></div>';}
