  function medals(el){el.querySelectorAll('.badges .badge').forEach((b,i)=>{if(b.querySelector('.x11med'))return;const B=BADGES[i];if(!B)return;const ok=!b.classList.contains('locked');const bi=b.querySelector('.bi');if(!bi)return;const ico=bi.innerHTML;bi.outerHTML='<span class="x11mw">'+medal(B.ic,ok)+'<span class="x11mi'+(ok?'':' off')+'">'+ico+'</span></span>';});}
  /* --- atalhos do ícone (?a=) --- */
  function shortcut(){try{const a=new URLSearchParams(location.search).get('a');if(!a)return;history.replaceState(null,'',location.pathname);setTimeout(()=>{if(document.getElementById('x8onb'))return;if(a==='praticar')startSess(weakTypes(1).length?'weak':'mix');else if(a==='cartoes')X10.open();else if(a==='tutor'){commTab='ai';go('comm');}else if(a==='exame')exam();},1200);}catch(e){}}
  return{tool,toolsHTML,nexMsg,goalHTML,bindHome,checkLevel,examTick:()=>{if(!EXI)EXI=setInterval(examTick,500);examTick();},a11yHTML,bindA11y,applyA11y,medals,shortcut,calcEval,sheet};
