/* 1.25: ações de uma mensagem num menu (antes «apagar/denunciar» em texto pequeno em todas) */
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-more]');if(!b)return;e.preventDefault();const box=b.closest('.msg')||b.parentElement,del=box.querySelector('[data-del]'),rp=box.querySelector('[data-rep]');
  if(typeof X11==='undefined'){(del||rp)&&(del||rp).click();return;}
  const sh=X11.sheet('Mensagem','<div class="x25acts">'+(del?'<button class="x8p gh w" id="x25-del">Apagar mensagem</button>':'')+(rp?'<button class="x8p gh w" id="x25-rep">Denunciar mensagem</button>':'')+'<button class="x8p l w" id="x25-x">Cancelar</button></div>');
  const q=id=>sh.sh.querySelector(id);if(q('#x25-del'))q('#x25-del').onclick=()=>{sh.close();del.click();};if(q('#x25-rep'))q('#x25-rep').onclick=()=>{sh.close();rp.click();};q('#x25-x').onclick=sh.close;});
/* 1.25: «O que estudas?» — o ano e as disciplinas. Usado no Início (ordem), nas disciplinas (ano aberto) e no Nex. */
function estudoGet(){try{return JSON.parse(localStorage.getItem('x25-estudo')||'null');}catch(e){return null;}}
function estudoCard(){const E0=estudoGet();if(E0&&E0.ano)return'';const D=window.XD?XD.DISC:[];
  return'<div class="card x25est" id="x25-est"><div class="eyebrow">Para começar</div><h2>O que estudas?</h2><p class="muted">Assim o Pronex abre logo a matéria do teu ano.</p><div class="x25yr" role="radiogroup" aria-label="Ano">'+[10,11,12].map(a=>'<button role="radio" aria-checked="false" data-ano="'+a+'">'+a+'.º ano</button>').join('')+'</div>'+
   '<div class="x25ds">'+[['mat','Matemática']].concat(D.map(d=>[d.id,d.n])).map(([k,n])=>'<button aria-pressed="false" data-dsel="'+k+'">'+esc(n)+'</button>').join('')+'</div><button class="x8p l w" id="x25-ok" disabled>Guardar</button></div>';}
function bindEstudo(el){const c=el.querySelector('#x25-est');if(!c)return;let ano=null;const sel=new Set();
  c.querySelectorAll('[data-ano]').forEach(b=>b.onclick=()=>{ano=+b.dataset.ano;c.querySelectorAll('[data-ano]').forEach(x=>x.setAttribute('aria-checked',String(x===b)));c.querySelector('#x25-ok').disabled=false;});
  c.querySelectorAll('[data-dsel]').forEach(b=>b.onclick=()=>{const k=b.dataset.dsel;sel.has(k)?sel.delete(k):sel.add(k);b.setAttribute('aria-pressed',String(sel.has(k)));});
  c.querySelector('#x25-ok').onclick=()=>{try{localStorage.setItem('x25-estudo',JSON.stringify({ano,disc:[...sel]}));}catch(e){}toast('Guardado. Podes mudar nas Definições.');c.remove();};}

